package cloud.foxlin.aegir.security;
import com.sun.net.httpserver.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import javax.net.ssl.*;
public final class DiagnosticsLifetimeTest{
 static Path keyStore;static int passed;interface Test{void run()throws Exception;}
 static void test(String name,Test body)throws Exception{body.run();passed++;System.out.println("PASS "+name);}static void check(boolean v,String why){if(!v)throw new AssertionError(why);}static void reject(Test f)throws Exception{try{f.run();}catch(Exception expected){return;}throw new AssertionError("Unsafe state accepted");}
 static void uncooperative(CountDownLatch release){while(release.getCount()>0)try{release.await();}catch(InterruptedException ignored){/* Demonstrates host code that ignores cancellation. */}}
 public static void main(String[]args)throws Exception{keyStore=Path.of(args[0]);for(String phase:Arrays.asList("request.start","request.complete")){for(String mode:Arrays.asList("deadline","interrupt","close")){test("diagnostic-"+phase+"-"+mode,()->lifetime(phase,mode));}}
  test("diagnostic-throw-sanitized-best-effort",()->{try(Fixture f=new Fixture();AegirSecurityClient c=f.client(new AegirDiagnosticsHooks(e->{throw new RuntimeException("synthetic-private-diagnostic");},e->{throw new RuntimeException("synthetic-private-diagnostic");},e->{throw new RuntimeException("synthetic-private-diagnostic");}),Duration.ofSeconds(2))){c.getIdentityGraph("developer:dev_123");}});
  test("diagnostic-global-resource-budget",DiagnosticsLifetimeTest::budget);
  test("journal-fresh-valid-missing-established-truncated",()->{Path path=Files.createTempDirectory("aegir-java-established-").resolve("journal");try(FileAuthorizationJournal j=new FileAuthorizationJournal(path)){check(j.stats().receipts==0,"Fresh creation failed");}Path guard=path.resolveSibling("journal.lock");byte[]guardBefore=Files.readAllBytes(guard);try(FileAuthorizationJournal j=new FileAuthorizationJournal(path)){check(!j.stats().connected,"Restart connected without reconciliation");}Files.delete(path);reject(()->{try(FileAuthorizationJournal j=new FileAuthorizationJournal(path)){}});check(!Files.exists(path)&&Arrays.equals(guardBefore,Files.readAllBytes(guard)),"Missing established state silently reset");Path unproven=path.resolveSibling("unproven");Files.createFile(unproven.resolveSibling("unproven.lock"));reject(()->{try(FileAuthorizationJournal j=new FileAuthorizationJournal(unproven)){}});check(!Files.exists(unproven),"Crash-before-initialization reset");Path corrupt=path.resolveSibling("corrupt");try(FileAuthorizationJournal j=new FileAuthorizationJournal(corrupt)){}Files.writeString(corrupt,"{");reject(()->{try(FileAuthorizationJournal j=new FileAuthorizationJournal(corrupt)){}});check(Files.readString(corrupt).equals("{"),"Corruption overwritten");});
  System.out.println("{\"suite\":\"java-diagnostics-lifetime\",\"passed\":"+passed+",\"failed\":0,\"skipped\":0}");}
 static void lifetime(String phase,String mode)throws Exception{CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AtomicBoolean block=new AtomicBoolean(phase.equals("request.start"));AtomicBoolean success=new AtomicBoolean();AtomicReference<Throwable>error=new AtomicReference<>();try(Fixture f=new Fixture();AegirSecurityClient c=f.client(new AegirDiagnosticsHooks(e->{if(e.eventName().equals(phase)&&block.get()){entered.countDown();uncooperative(release);}},null,null),Duration.ofMillis(600))){if(phase.equals("request.complete")){c.getIdentityGraph("developer:dev_123");block.set(true);}Thread worker=new Thread(()->{try{c.getIdentityGraph("developer:dev_123");success.set(true);}catch(Throwable denied){error.set(denied);}},"aegir-native-diag-call");worker.start();check(entered.await(2,TimeUnit.SECONDS),"Callback not entered");long start=System.nanoTime();if(mode.equals("close"))c.close();if(mode.equals("interrupt"))worker.interrupt();worker.join(1500);check(!worker.isAlive()&&!success.get()&&error.get()!=null&&System.nanoTime()-start<1500000000L,"Hook defeated lifetime or adopted late result");release.countDown();Thread.sleep(20);check(!success.get(),"Late callback adopted a result");}finally{release.countDown();}}
 static void budget()throws Exception{Semaphore entered=new Semaphore(0);CountDownLatch release=new CountDownLatch(1);List<AegirSecurityClient>clients=new ArrayList<>();List<Thread>threads=new ArrayList<>();AtomicInteger success=new AtomicInteger();try(Fixture f=new Fixture()){for(int i=0;i<4;i++){AegirSecurityClient c=f.client(new AegirDiagnosticsHooks(null,null,e->{entered.release();uncooperative(release);}),Duration.ofMillis(300));clients.add(c);Thread t=new Thread(()->{try{c.getIdentityGraph("developer:dev_123");success.incrementAndGet();}catch(Exception denied){}});threads.add(t);t.start();check(entered.tryAcquire(2,TimeUnit.SECONDS),"Budget worker not entered");}for(Thread t:threads){t.join(1500);check(!t.isAlive(),"Uncooperative hook blocked caller");}check(success.get()==0,"Hung hook returned success");long count=Thread.getAllStackTraces().keySet().stream().filter(t->t.isAlive()&&t.getName().equals("aegir-security-diagnostics")).count();check(count<=4,"Callback worker budget exceeded");AtomicInteger extra=new AtomicInteger();try(AegirSecurityClient c=f.client(new AegirDiagnosticsHooks(e->extra.incrementAndGet(),null,null),Duration.ofSeconds(2))){c.getIdentityGraph("developer:dev_123");check(extra.get()==0,"Saturated hooks queued or expanded workers");}}finally{release.countDown();for(AegirSecurityClient c:clients)c.close();}}
 static final class Fixture implements AutoCloseable{final HttpsServer server;final ExecutorService workers=Executors.newFixedThreadPool(2);final String base,pin;Fixture()throws Exception{char[]password=System.getenv("AEGIR_JAVA_TEST_KEYSTORE_PASS").toCharArray();KeyStore store=KeyStore.getInstance("PKCS12");try(InputStream input=Files.newInputStream(keyStore)){store.load(input,password);}KeyManagerFactory keys=KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());keys.init(store,password);Arrays.fill(password,'\0');SSLContext tls=SSLContext.getInstance("TLS");tls.init(keys.getKeyManagers(),null,null);server=HttpsServer.create(new InetSocketAddress("127.0.0.1",0),0);server.setHttpsConfigurator(new HttpsConfigurator(tls));server.setExecutor(workers);server.createContext("/",x->{byte[]body=LegacySecurityHardeningTest.GRAPH.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json");try{x.sendResponseHeaders(200,body.length);x.getResponseBody().write(body);}finally{x.close();}});server.start();base="https://127.0.0.1:"+server.getAddress().getPort();pin=AuthorizationIntegration.hex(MessageDigest.getInstance("SHA-256").digest(store.getCertificate("aegir-test").getEncoded()));}AegirSecurityClient client(AegirDiagnosticsHooks hooks,Duration timeout){return AegirSecurityClient.pinnedLoopbackDevelopment(base,"synthetic-developer-key",pin,timeout,hooks);}public void close()throws Exception{server.stop(0);workers.shutdownNow();workers.awaitTermination(2,TimeUnit.SECONDS);}}
}
